export const collection=(db,root,uid,name)=>({name});export const doc=(db,root,uid,name,id)=>({name,id});
export function onSnapshot(ref,opts,fn,fail){const w={name:ref.name,fn};window.fakeCloud.watchers.push(w);setTimeout(()=>emit(w),1);return()=>{window.fakeCloud.watchers=window.fakeCloud.watchers.filter(x=>x!==w)}}
function emit(w){const docs=[...window.fakeCloud.data.entries()].filter(([k])=>k.startsWith(w.name+'/')).map(([k,v])=>({id:k.slice(w.name.length+1),data:()=>structuredClone(v)}));w.fn({docs,metadata:{fromCache:false,hasPendingWrites:false}})}
export async function runTransaction(db,callback){let write;const tx={get:async ref=>{const v=window.fakeCloud.data.get(ref.name+'/'+ref.id);return {exists:()=>!!v,data:()=>structuredClone(v)}},set:(ref,data)=>{write={ref,data}}};const result=await callback(tx);if(write){window.fakeCloud.data.set(write.ref.name+'/'+write.ref.id,structuredClone(write.data));for(const w of [...window.fakeCloud.watchers])if(w.name===write.ref.name)setTimeout(()=>emit(w),10)}return result}
